  const mobile = useMobileSelectionMenu(enabled && isCoarse)

  const active = isCoarse ? mobile : desktop

  console.log('[ctxmenu] render — enabled:', enabled, '| isCoarse:', isCoarse, '| isOpen:', active.isOpen)

  return active
}

