function placeScatter(geom, mat, count, y) {
  for (let i = 0; i < count; i++) {
    let x, z, ok = false;
    for (let r = 0; r < SCATTER_RETRIES && !ok; r++) {
      x = (Math.random() * 2 - 1) * SCATTER_BOUND;
      z = (Math.random() * 2 - 1) * SCATTER_BOUND;
      if (Math.abs(x) < SCATTER_X_MIN) continue;            // outside corridor
      ok = !sandZones.some(s =>
        (x - s.x) ** 2 + (z - s.z) ** 2 < (s.r + 0.5) ** 2  // outside sand
      );
    }
    if (!ok) continue;
    const m = new THREE.Mesh(geom, mat);
    m.position.set(x, y, z);
    m.rotation.y = Math.random() * Math.PI * 2;
    m.scale.setScalar(0.8 + Math.random() * 0.5);
    scene.add(m);
  }
}
