// main.js:979-1008
function tick() {
  const dt = Math.min(clock.getDelta(), 0.05);
  const wasOnSand = pointInAnyZone(carRig.position.x, carRig.position.z, sandZones);

  applyThrottleAndSteering(dt, wasOnSand);
  advanceHorizontalPosition(dt);

  const terrainSample = sampleTerrainState();
  updateVerticalMotion(dt, terrainSample);
  updateCarPose(dt, terrainSample.terrainPitch);

  updateExhaust();
  updateCamera();
  driveState.cameraShake = THREE.MathUtils.damp(driveState.cameraShake, 0, 10, dt);

  updateClouds(dt);
  updateDustTrail(dt, terrainSample.onSand);
  updateFinishState();

  audioController.update({
    speedNorm: driveState.speed / MAX_SPEED,
    throttlePressed: keys.f,
    onSand: terrainSample.onSand,
    finished: driveState.finished,
    dt,
  });

  renderer.render(scene, camera);
  requestAnimationFrame(tick);
}

