};

// audio-controller.js:108-124
update({ speedNorm, throttlePressed, onSand, finished, dt }) {
  if (!this.audioEnabled) return;

  if (finished && !this.finished) this.snds.finish.play();
  this.finished = finished;

  const targetLoopMaster = finished ? 0 : 1;
  this.loopMaster += (targetLoopMaster - this.loopMaster) * Math.min(1, CFG.loopFadeRate * dt);
  this.loopMaster = clamp01(this.loopMaster);

  if (throttlePressed && !finished) {
    if (!this.throttlePressed) this.playAccelLayer();
    else if (this.snds.accel.playing()) this.snds.accel.volume(CFG.volAccel * this.loopMaster);
  } else if (this.throttlePressed) {
    this.fadeOutAccelLayer();
  }
  this.throttlePressed = throttlePressed && !finished;

