#!/usr/bin/env node
const { execSync } = require('child\_process');
const fs = require('fs');
const path = require('path');
let input = '';
process.stdin.on('data', chunk => input += chunk);
process.stdin.on('end', () => {
const data = JSON.parse(input);
const model = data.model.display\_name;
const dir = path.basename(data.workspace.current\_dir);
const sessionId = data.session\_id;
const CACHE\_FILE = `/tmp/statusline-git-cache-${sessionId}`;
const CACHE\_MAX\_AGE = 5; // seconds
const cacheIsStale = () => {
if (!fs.existsSync(CACHE\_FILE)) return true;
return (Date.now() / 1000) - fs.statSync(CACHE\_FILE).mtimeMs / 1000 > CACHE\_MAX\_AGE;
};
if (cacheIsStale()) {
try {
execSync('git rev-parse --git-dir', { stdio: 'ignore' });
const branch = execSync('git branch --show-current', { encoding: 'utf8' }).trim();
const staged = execSync('git diff --cached --numstat', { encoding: 'utf8' }).trim().split('\n').filter(Boolean).length;
const modified = execSync('git diff --numstat', { encoding: 'utf8' }).trim().split('\n').filter(Boolean).length;
fs.writeFileSync(CACHE\_FILE, `${branch}|${staged}|${modified}`);
} catch {
fs.writeFileSync(CACHE\_FILE, '||');
}
}
const [branch, staged, modified] = fs.readFileSync(CACHE\_FILE, 'utf8').trim().split('|');
if (branch) {
console.log(`[${model}] 📁 ${dir} | 🌿 ${branch} +${staged} ~${modified}`);
} else {
console.log(`[${model}] 📁 ${dir}`);
}
});

