  const fence = text.match(/```(?:json)?\s*([\s\S]*?)```/i);
  try {
    const value = JSON.parse(fence ? fence[1] : text);
    if (value && typeof value === "object" && requiredKeys.every((k) => k in value)) return { ok: true, value };
  } catch {
    // fall through
  }
  return { ok: false, raw: text };
}

