      type: summaryDataReducer.SummaryDataEventType.SUMMARY_LOAD_FAILED,
      errorMessage: result.error,
    })
  }
}

export function reduceSummaryData(summaryData, event) {
  switch (event.type) {
    case SummaryDataEventType.SUMMARY_REQUESTED:
      return { state: 'loading', patch: { status: 'loading', effort, errorMessage: null } }

    case SummaryDataEventType.SUMMARY_LOAD_SUCCEEDED:
      return { state: 'available', patch: { status: 'available', markdown, effort, checkedAt, errorMessage: null } }

    case SummaryDataEventType.SUMMARY_LOAD_FAILED:
      return { state: 'error', patch: { status: 'error', errorMessage } }

    case SummaryDataEventType.SUMMARY_ROLLBACK:
      return { state: getSummaryDataStatus(event.previousData), patch: event.previousData }
  }
}

