const CAR_CLEARANCE = 0.6;
const CAR_PITCH_SAMPLE = 1.4;
const GROUND_SEGMENTS = 80;
const TERRAIN_FEATURES = [
  { x: -2, z: 68, rx: 18, rz: 24, h: 1.2 },
  { x:  3, z: 34, rx: 22, rz: 18, h: 1.8 },
  { x: -1, z:  0, rx: 28, rz: 22, h: 3.2 }, // hero dune
  { x:  4, z: -34, rx: 20, rz: 24, h: 1.7 },
  { x: -3, z: -66, rx: 18, rz: 20, h: 1.1 },
];

function lobeHeight(x, z, f) {
  const dx = (x - f.x) / f.rx;
  const dz = (z - f.z) / f.rz;
  const q = 1 - dx * dx - dz * dz;
  if (q <= 0) return 0;
  return f.h * q * q;
}

function heightAt(x, z) {
  let y = 0;
  for (const f of TERRAIN_FEATURES) y += lobeHeight(x, z, f);
  return y;
}

const groundGeom = new THREE.PlaneGeometry(
  GROUND_SIZE,
  GROUND_SIZE,
  GROUND_SEGMENTS,
  GROUND_SEGMENTS
);
const pos = groundGeom.attributes.position;
for (let i = 0; i < pos.count; i++) {
  const x = pos.getX(i);
  const z = -pos.getY(i);   // plane is XY before rotation
  pos.setZ(i, heightAt(x, z));
}
pos.needsUpdate = true;
groundGeom.computeVertexNormals();

if (keys.f) speed += ACCEL * dt;
if (keys.b) speed -= FRICTION * 4 * dt;
else if (!keys.f) speed -= Math.sign(speed) * FRICTION * dt;
if (speed < 0) speed = 0;
if (speed > MAX_SPEED) speed = MAX_SPEED;

const car = new THREE.Group();
const carVisual = new THREE.Group();
car.add(carVisual);

const fx = car.position.x - Math.sin(heading) * CAR_PITCH_SAMPLE;
const fz = car.position.z - Math.cos(heading) * CAR_PITCH_SAMPLE;
const bx = car.position.x + Math.sin(heading) * CAR_PITCH_SAMPLE;
const bz = car.position.z + Math.cos(heading) * CAR_PITCH_SAMPLE;

const frontY = heightAt(fx, fz);
const backY = heightAt(bx, bz);
const pitch = Math.atan2(frontY - backY, CAR_PITCH_SAMPLE * 2);

car.position.y = heightAt(car.position.x, car.position.z) + CAR_CLEARANCE;
car.rotation.y = heading;
carVisual.rotation.x = pitch;

function addMarkerPair(z, color) {
  const mat = new THREE.MeshLambertMaterial({ color, flatShading: true });
  const geom = new THREE.BoxGeometry(0.5, 2.4, 0.5);

  for (const x of [-TRACK_HALF_W, TRACK_HALF_W]) {
    const post = new THREE.Mesh(geom, mat);
    post.position.set(x, heightAt(x, z) + 1.2, z);
    scene.add(post);
  }
}

